import { EventEmitter } from 'node:events';
class Svc extends EventEmitter { n: number = 0; run(): void { this.n++; this.emit('ran', this.n); } }
function main(): void {
  const s = new Svc();
  s.on('ran', (n: number) => console.log('ran', n));
  s.once('ran', (n: number) => console.log('once', n));
  s.run(); s.run();
  console.log(s instanceof EventEmitter, s instanceof Svc, s.listenerCount('ran'), s.eventNames());
  try { s.emit('error', new Error('boom')); } catch (e: any) { console.log(e.message); }
}
